sequence.script:

var data = mc.getPayloadJSON();
 var customers = data.customers;
  var totalConsumptions = 0;
      var totalEnergyCharges = 0;
        var totalpreviousBalances = 0;
      var totalpayables = 0;
      var lowRiskCustomers = 0;
      var mediumRiskCustomers = 0;
      var highRiskCustomers = 0;

      for (var i = 0; i < customers.length; i++)
      {
       totalConsumptions += Number(customers[i].totalConsumption);
       totalEnergyCharges += Number(customers[i].totalEnergyCharge);
        totalpreviousBalances += Number(customers[i].previousBalance);
         totalpayables += Number(customers[i].totalpayable);
         {
           if(customers[i].risklevel == "LOW_RISK"){
      lowRiskCustomers++;
       }
       else if(customers[i].risklevel == "MEDIUM_RISK"){
      mediumRiskCustomers++;
       }
       else if(customers[i].risklevel == "HIGH_RISK"){
      highRiskCustomers++;
       }
       }
       }

       mc.setProperty("totalConsumptions",totalConsumptions);
         mc.setProperty("totalEnergyCharges",totalEnergyCharges);
           mc.setProperty("totalpreviousBalances",totalpreviousBalances);
             mc.setProperty("totalpayables",totalpayables);
               mc.setProperty("lowRiskCustomers",lowRiskCustomers);
                 mc.setProperty("mediumRiskCustomers",mediumRiskCustomers);
                    mc.setProperty("highRiskCustomers",highRiskCustomers);
